export function fetchOrder(orderId: string): Promise<Order> {
  return request<Order>(`/orders/${encodeURIComponent(orderId)}`)
}

export function updateOrder(order: Order): Promise<Order> {
  const { customerId, productId, quantity } = order
  return request<Order>(`/orders/${order.id}`, { method: "PUT", body: JSON.stringify({ customerId, productId, quantity }) })
}

